        private OpCode GetMoveInstruction(ExprType type)
        {
            if (type == ExprType.Long || type == ExprType.UnsignedLong ||
                type == ExprType.LongLong || type == ExprType.UnsignedLongLong)
                return VMLPlugins.CompilerOptionsContext.Current.Int64Mode == VMLPlugins.Int64Mode.Hard ? OpCode.MOVEL : OpCode.MOVE;
            var (s, f, d) = TypeInfo(type);
            return ExpressionManager.SelectMoveOp(s, f, d);
        }

